'use client';

import { Cleaner } from '@/types/booking';
import { authenticateCleaner } from './actions-auth';

/**
 * Client-side authentication for cleaners
 * Authenticates using database passwords (not Supabase Auth)
 */
export async function authenticateCleanerClient(
  phone: string,
  password: string
): Promise<{
  success: boolean;
  cleaner?: Cleaner;
  error?: string;
}> {
  try {
    // Trim inputs
    const trimmedPhone = phone.trim();
    const trimmedPassword = password.trim();
    
    if (!trimmedPhone || !trimmedPassword) {
      return { success: false, error: 'Phone number and password are required' };
    }
    
    // Call server action to authenticate
    const result = await authenticateCleaner(trimmedPhone, trimmedPassword);
    
    if (!result.success) {
      return result;
    }

    // Note: Session management will need to be handled separately
    // For now, we're just authenticating against the database
    // The layout and other components using Supabase Auth will need to be updated
    // to use a custom session system
    
    return result;
  } catch (error) {
    console.error('Error in authenticateCleanerClient:', error);
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Authentication failed',
    };
  }
}
